using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Security.Cryptography;using CodexLight.Shared;
namespace CodexLight.Bootstrap {
 [DataContract]internal sealed class UpgradeContext {
  [DataMember(Order=0)]public int Version=1;
  [DataMember(Order=1)]public string OldReceipt="";
  [DataMember(Order=2)]public string NewReceipt="";
  [DataMember(Order=3)]public string OldHash="";
  [DataMember(Order=4)]public string StageId="";
 }
 internal sealed class UpgradePreview {
  public UpgradePlan Plan{get;}public InstallReceipt NextReceipt{get;}internal byte[] OldReceiptBytes{get;}
  public UpgradePreview(UpgradePlan plan,InstallReceipt next,byte[] oldBytes){Plan=plan;NextReceipt=next;OldReceiptBytes=oldBytes;}
 }
 internal sealed class UpgradeOrchestrator {
  readonly string root,identity,source;readonly List<UpgradeFile> trusted;readonly IUpgradeRegistration registry;readonly Func<IDisposable> acquire;readonly Func<bool> running;readonly Func<string,bool,InstallReceipt> recognizeLegacy;
  const string ContextName="CodexLight.upgrade-context.json";
  public UpgradeOrchestrator(string root,string identity,string source,IEnumerable<UpgradeFile> trustedFiles,IUpgradeRegistration registry,Func<IDisposable>? acquire=null,Func<bool>? running=null,Func<string,bool,InstallReceipt>? recognizeLegacy=null){this.root=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar);this.identity=identity;this.source=Path.GetFullPath(source);trusted=UpgradePlanner.ValidateFiles(trustedFiles);this.registry=registry;this.acquire=acquire??(()=>InstallMaintenance.Acquire(root));this.running=running??(()=>TargetRunning(root));this.recognizeLegacy=recognizeLegacy??LegacyRepair.Recognize;}
  static bool TargetRunning(string target){foreach(var process in Process.GetProcessesByName("CodexLight"))using(process){try{if(process.HasExited)continue;var file=process.MainModule?.FileName;if(file==null)throw new InvalidOperationException();if(string.Equals(Path.GetFullPath(file),Path.Combine(target,"CodexLight.exe"),StringComparison.OrdinalIgnoreCase))return true;}catch{throw new InvalidOperationException("无法核实旧版本进程路径；请先关闭 Codex Light 后重试，不会强制终止。");}}return false;}
  static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static byte[] Serialize(UpgradeContext c){using(var s=new MemoryStream()){new DataContractJsonSerializer(typeof(UpgradeContext)).WriteObject(s,c);return s.ToArray();}}
  void NoLinks(string file){for(string? item=file;!string.IsNullOrEmpty(item);item=Path.GetDirectoryName(item))if((File.Exists(item)||Directory.Exists(item))&&(File.GetAttributes(item)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("维护路径不能经过链接");}
  void Stopped(){NoLinks(root);if(running())throw new InvalidOperationException("请先正常关闭此目录的 Codex Light；不会强制终止。");}
  List<UpgradeFile> Observe(InstallReceipt old){var known=old.Files.ToDictionary(f=>f.Path,StringComparer.OrdinalIgnoreCase);var output=new List<UpgradeFile>();var pending=new Stack<string>();pending.Push(root);while(pending.Count>0){foreach(var item in Directory.GetFileSystemEntries(pending.Pop())){NoLinks(item);string relative=item.Substring(root.Length+1).Replace(Path.DirectorySeparatorChar,'/');if(relative==UpgradeReceiptCodec.Filename||relative==ContextName||relative=="CodexLight.upgrade-journal.json"||relative=="CodexLight.upgrade.lock")continue;if(Directory.Exists(item)){if(relative.StartsWith("CodexLight.upgrade-",StringComparison.Ordinal)&&!relative.Contains('/'))continue;pending.Push(item);continue;}if(output.Count>=10000)throw new InvalidOperationException("目录内容过多，需要人工审查");var info=new FileInfo(item);output.Add(new UpgradeFile(relative,info.Length,known.TryGetValue(relative,out var expected)&&info.Length==expected.Size?BoundedFile.Hash(item,expected.Size):new string('0',64)));}}return output;}
  UpgradePreview BuildPreview(){Stopped();if(File.Exists(Path.Combine(root,ContextName))||File.Exists(Path.Combine(root,"CodexLight.upgrade-journal.json")))throw new InvalidOperationException("存在未结束维护，请先明确选择恢复");var codec=new WindowsUpgradeRegistration(identity);var reg=codec.Parse(registry.Read());if(!reg.Exists||string.IsNullOrEmpty(reg.ReceiptHash))throw new InvalidOperationException("未登记或旧版本无receipt，请使用精确遗留修复入口");var receiptPath=Path.Combine(root,UpgradeReceiptCodec.Filename);NoLinks(receiptPath);var bytes=BoundedFile.Read(receiptPath,1024*1024);var old=UpgradeReceiptCodec.Decode(bytes,reg.ReceiptHash,identity);if(old.InstallId!=reg.InstallId)throw new InvalidOperationException("登记ID不匹配");var next=new InstallReceipt(old.InstallId,identity,trusted);var plan=UpgradePlanner.Create(old,reg.InstallLocation,reg.UninstallString,reg.ReceiptHash,trusted,Observe(old),false);return new UpgradePreview(UpgradeReceiptCodec.Attach(plan,bytes,next),next,bytes);}
  public UpgradePreview Preview(){using(acquire())return BuildPreview();}
  public void Apply(UpgradePreview preview,bool confirmed){if(!confirmed)throw new InvalidOperationException("必须确认预览后升级");using(acquire()){
   var fresh=BuildPreview();if(preview.Plan.ReceiptHash!=fresh.Plan.ReceiptHash||UpgradeReceiptCodec.Encode(preview.NextReceipt).SequenceEqual(UpgradeReceiptCodec.Encode(fresh.NextReceipt))==false)throw new InvalidOperationException("预览已变化，请重新确认");
   string stageId=Guid.NewGuid().ToString("N"),stage=Path.Combine(Path.GetDirectoryName(root)!,"CodexLight.payload-"+stageId);if(Directory.Exists(stage)||File.Exists(stage))throw new InvalidOperationException("临时路径冲突");NoLinks(stage);Directory.CreateDirectory(stage);
   foreach(var file in trusted){string input=Path.Combine(source,file.Path.Replace('/',Path.DirectorySeparatorChar)),output=Path.Combine(stage,file.Path.Replace('/',Path.DirectorySeparatorChar));NoLinks(input);if(new FileInfo(input).Length!=file.Size||BoundedFile.Hash(input,file.Size)!=file.Sha256.ToLowerInvariant())throw new InvalidOperationException("新安装包校验失败");Directory.CreateDirectory(Path.GetDirectoryName(output)!);BoundedFile.Copy(input,output,file.Size);}
   var nextBytes=UpgradeReceiptCodec.Encode(fresh.NextReceipt);File.WriteAllBytes(Path.Combine(stage,UpgradeReceiptCodec.Filename),nextBytes);
   var context=new UpgradeContext{OldReceipt=Convert.ToBase64String(fresh.OldReceiptBytes),NewReceipt=Convert.ToBase64String(nextBytes),OldHash=fresh.Plan.ReceiptHash,StageId=stageId};string contextPath=Path.Combine(root,ContextName);using(var f=new FileStream(contextPath,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] bytes=Serialize(context);f.Write(bytes,0,bytes.Length);f.Flush(true);}
   var transaction=new UpgradeTransaction(root,stage,fresh.Plan,registry,running);transaction.Execute(true,new WindowsUpgradeRegistration(identity).Next(fresh.NextReceipt));ArchiveCompleted(transaction,contextPath);CleanupStage(stage,fresh.NextReceipt);
  }}
  void ArchiveCompleted(UpgradeTransaction transaction,string contextPath){string state=transaction.Recover(true);if(state!="committed"&&state!="rolled-back")throw new InvalidOperationException("维护结果不明确");string journal=Path.Combine(root,"CodexLight.upgrade-journal.json");var bytes=BoundedFile.Read(journal,256*1024);UpgradeJournalRecord record;using(var input=new MemoryStream(bytes))record=(UpgradeJournalRecord)new DataContractJsonSerializer(typeof(UpgradeJournalRecord)).ReadObject(input)!;string backup=Path.Combine(root,"CodexLight.upgrade-"+record.TransactionId);NoLinks(backup);foreach(var pair in new[]{new[]{contextPath,Path.Combine(backup,"context.json")},new[]{journal,Path.Combine(backup,"journal.json")}}){NoLinks(pair[1]);if(File.Exists(pair[1])){if(!BoundedFile.Read(pair[0],pair[0]==journal?256*1024:4*1024*1024).SequenceEqual(BoundedFile.Read(pair[1],pair[0]==journal?256*1024:4*1024*1024)))throw new InvalidOperationException("归档记录冲突，保留原记录");}else BoundedFile.CopyMetadata(pair[0],pair[1],pair[0]==journal?256*1024:4*1024*1024);}File.Delete(journal);File.Delete(contextPath);}
  public string Recover(bool confirmed,bool removeVerifiedStaleLock=false){if(!confirmed)throw new InvalidOperationException("恢复需要明确确认");using(acquire()){
   Stopped();var contextPath=Path.Combine(root,ContextName);NoLinks(contextPath);var bytes=BoundedFile.Read(contextPath,4*1024*1024);if(bytes.Length>4*1024*1024)throw new InvalidOperationException("恢复记录过大");UpgradeContext context;using(var s=new MemoryStream(bytes))context=(UpgradeContext)new DataContractJsonSerializer(typeof(UpgradeContext)).ReadObject(s)!;if(context.Version!=1||!Serialize(context).SequenceEqual(bytes)||!Guid.TryParseExact(context.StageId,"N",out _))throw new InvalidOperationException("恢复记录格式无效");
   var oldBytes=Convert.FromBase64String(context.OldReceipt);var old=UpgradeReceiptCodec.Decode(oldBytes,context.OldHash,identity);var expectedNext=new InstallReceipt(old.InstallId,identity,trusted);if(!UpgradeReceiptCodec.Encode(expectedNext).SequenceEqual(Convert.FromBase64String(context.NewReceipt)))throw new InvalidOperationException("需要原升级安装包恢复，不能用其他版本猜测");
   var basePlan=UpgradePlanner.Create(old,identity,"\""+identity+"\\Uninstall.exe\" /uninstall",old.Fingerprint(),trusted,old.Files,false);var plan=UpgradeReceiptCodec.Attach(basePlan,oldBytes,expectedNext);var stage=Path.Combine(Path.GetDirectoryName(root)!,"CodexLight.payload-"+context.StageId);NoLinks(stage);var transaction=new UpgradeTransaction(root,stage,plan,registry,running);
   // Validates canonical journal, plan binding, paths and workspace before touching a stale lock.
   string liveJournal=Path.Combine(root,"CodexLight.upgrade-journal.json");if(!File.Exists(liveJournal)){var candidates=Directory.GetDirectories(root,"CodexLight.upgrade-*").Where(folder=>{NoLinks(folder);string archivedContext=Path.Combine(folder,"context.json");NoLinks(archivedContext);return File.Exists(archivedContext)&&BoundedFile.Read(archivedContext,4*1024*1024).SequenceEqual(bytes);}).Take(2).ToArray();if(candidates.Length==0){if(File.Exists(liveJournal+".new"))throw new InvalidOperationException("日志写入不完整，需人工核验；不猜测状态");var registration=new WindowsUpgradeRegistration(identity).Parse(registry.Read());if(registration.ReceiptHash!=old.Fingerprint())throw new InvalidOperationException("缺少日志且登记已变化，不能认定未执行");foreach(var file in old.Files){string current=Path.Combine(root,file.Path.Replace('/',Path.DirectorySeparatorChar));NoLinks(current);if(!File.Exists(current)||new FileInfo(current).Length!=file.Size||BoundedFile.Hash(current,file.Size)!=file.Sha256.ToLowerInvariant())throw new InvalidOperationException("缺少日志且文件变化，保留记录等待人工恢复");}if(File.Exists(Path.Combine(root,"CodexLight.upgrade.lock")))throw new InvalidOperationException("缺少可验证日志，不能删除遗留锁");Directory.CreateDirectory(stage);BoundedFile.CopyMetadata(contextPath,Path.Combine(stage,"not-started-context.json"),4*1024*1024);File.Delete(contextPath);return "not-started";}if(candidates.Length!=1)throw new InvalidOperationException("无法唯一确定已归档恢复记录");string archivedJournal=Path.Combine(candidates[0],"journal.json");NoLinks(archivedJournal);BoundedFile.CopyMetadata(archivedJournal,liveJournal,256*1024);}
   transaction.ValidateRecovery();string lockPath=Path.Combine(root,"CodexLight.upgrade.lock");if(File.Exists(lockPath)){if(!removeVerifiedStaleLock)throw new InvalidOperationException("发现遗留维护锁；已核验记录，需明确确认移除该锁后恢复");NoLinks(lockPath);using(var test=new FileStream(lockPath,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){if(test.Length!=0)throw new InvalidOperationException("未知锁文件，不自动移除");}File.Delete(lockPath);}
   string state=transaction.Recover(true);ArchiveCompleted(transaction,contextPath);CleanupStage(stage,expectedNext);return state;
  }}
  void CleanupStage(string stage,InstallReceipt next){try{NoLinks(stage);foreach(var file in next.Files){string item=Path.Combine(stage,file.Path.Replace('/',Path.DirectorySeparatorChar));NoLinks(item);if(File.Exists(item)&&new FileInfo(item).Length==file.Size&&BoundedFile.Hash(item,file.Size)==file.Sha256.ToLowerInvariant())File.Delete(item);}string receipt=Path.Combine(stage,UpgradeReceiptCodec.Filename);NoLinks(receipt);if(File.Exists(receipt)&&BoundedFile.Read(receipt,1024*1024).SequenceEqual(UpgradeReceiptCodec.Encode(next)))File.Delete(receipt);var directories=new List<string>();var queue=new Stack<string>();queue.Push(stage);while(queue.Count>0){foreach(var dir in Directory.GetDirectories(queue.Pop())){NoLinks(dir);directories.Add(dir);queue.Push(dir);}}foreach(var dir in directories.OrderByDescending(x=>x.Length))if(!Directory.EnumerateFileSystemEntries(dir).Any())Directory.Delete(dir);if(!Directory.EnumerateFileSystemEntries(stage).Any())Directory.Delete(stage);}catch{/* Do not turn a verified upgrade into failure; unknown/locked staging data is retained. */}}
  public InstallReceipt RepairLegacy(bool confirmed){if(!confirmed)throw new InvalidOperationException("遗留修复需要明确确认");using(acquire()){Stopped();var receiptPath=Path.Combine(root,UpgradeReceiptCodec.Filename);if(File.Exists(Path.Combine(root,ContextName))||File.Exists(Path.Combine(root,"CodexLight.upgrade-journal.json")))throw new InvalidOperationException("已有恢复记录，不执行遗留认领");NoLinks(receiptPath);var receipt=recognizeLegacy(root,true);if(!string.Equals(receipt.Target,identity,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("遗留证据目标不匹配");bool existingReceipt=File.Exists(receiptPath);if(existingReceipt)receipt=UpgradeReceiptCodec.DecodeLegacyRepair(BoundedFile.Read(receiptPath,1024*1024),receipt);var bytes=UpgradeReceiptCodec.Encode(receipt);string previous=registry.Read();var previousRecord=new WindowsUpgradeRegistration(identity).Parse(previous);if(previousRecord.Exists&&!string.IsNullOrEmpty(previousRecord.ReceiptHash))throw new InvalidOperationException("已有归属登记，不执行重复认领或覆盖");if(!existingReceipt)using(var file=new FileStream(receiptPath,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(bytes,0,bytes.Length);file.Flush(true);}try{registry.Write(new WindowsUpgradeRegistration(identity).Next(receipt));}catch{if(!existingReceipt&&File.Exists(receiptPath)&&Hash(BoundedFile.Read(receiptPath,1024*1024))==Hash(bytes))File.Delete(receiptPath);if(registry.Read()!=previous)throw new InvalidOperationException("修复登记失败且恢复未确认，请保留目录并人工检查");throw;}return receipt;}}
 }
}
